#!/usr/bin/env python3
# =====================================================================
#  apply_dash_calm.py  —  fence DASH_CALM_20261117 (TD-029)
#  REQUIRES, in order: … → apply_dash_system.py → apply_book_strip.py
#  Dashboard only, plus one read-only admin route. No engine, order or strategy code.
#
#  The redesigned Dashboard (option B "Calm", chosen 17 Nov):
#   * hero: ONE big number (Live if it traded today, else Paper; the other
#     book beside it, never summed), a sentence that says what it means,
#     Today / This week / This month tabs, the day's chart fitted to the
#     time so far (hover for values)
#   * a card per strategy (its Live and Paper rows share a card), biggest
#     move first, with its spark, closed / open / legs, state badge and
#     Entry/Exit meter; tap the meter → the card widens and shows the
#     dial + conditions; tap the card → its panel and live chart below
#   * a dashed card per armed strategy that has not traded yet, with its
#     entry readiness; All / Live / Paper filter on a two-book day
#   * phone: same page stacked, Live | Paper switch for the big number,
#     meters inside the cards (no separate meter card)
#  New GET /api/replay/meters?strategies=… (admin wall): every card's
#  meter in one call; per-strategy 8 s cache, Kite top-up of bars at most
#  once a minute per strategy, max 24 strategies, one failure isolated.
#  App Settings → Dashboard layout: Modern (this, default) | Classic (the
#  previous Modern page, unchanged) | Legacy.
#
#  Files: pages/CalmDashboard.jsx + components/calm/* (NEW), Dashboard.jsx,
#  fleet/dashboardLayout.js, StrategyHost.jsx (meter prop), backend
#  api/live_replay_routes.py, api/app_settings_api.py,
#  api/test_dash_calm_routes.py (NEW); uitest: calm_fixture, shot_calm,
#  test_ui_calm (NEW), README; the previous page's suites now pick
#  layout "classic" (livechart_scene, shot_dashboard, test_ui_live_chart,
#  test_ui_dash_system, test_ui_off_hidden).
#
#  Run ONLY this script, outside market hours, after apply_book_strip.py:
#     cd ~/dev/scalp-app && python3 apply_dash_calm.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
#  UI checks (optional, app closed): cd frontend && CI=false npm run build &&
#     PYTHONPATH=../backend python3 uitest/test_ui_calm.py
#  Screens: PYTHONPATH=../backend python3 uitest/shot_calm.py /tmp/calm
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "DASH_CALM_20261117"
ITEMS = json.loads(r'''[{"path": "frontend/src/pages/CalmDashboard.jsx", "orig": null, "new": "d7b4174407c566e37efa5b87f840d05bb55e7d65f77a9fe3859082b61c388731", "blob": ""}, {"path": "frontend/src/components/calm/calm.js", "orig": null, "new": "4069862c75ee8fa53ab7c28a7f002d4a8d06470345497550c6a0d2d4df8c3ecd", "blob": ""}, {"path": "frontend/src/components/calm/useMeters.js", "orig": null, "new": "1e5250f32fe09d9397d900cd3f1becbe8bd31ecc5d832ae8809496618f595ea1", "blob": ""}, {"path": "frontend/src/components/calm/CalmChart.jsx", "orig": null, "new": "5ad2614777155e6868beb50c39ec54cac11c8a83208fc667ec5528a153e29b48", "blob": ""}, {"path": "frontend/src/components/calm/CalmHero.jsx", "orig": null, "new": "b7cf0efb467226fcada30abdb597383bb1173872e7f10e9089e252ead107cc75", "blob": ""}, {"path": "frontend/src/components/calm/StrategyCard.jsx", "orig": null, "new": "955adc8d8c96406647ccd9eedb0ab1a4f2eb5b7ed278c3498483e9f353957184", "blob": ""}, {"path": "frontend/src/pages/Dashboard.jsx", "orig": "90c91f292647972d7232b485d2f23f845ecbd6801f54eb4ff9d7c3891de4080f", "new": "dff4aa24ec6c945b0d6ff576a935edf19c15996d14810bb627b0d7b0133766dc", "blob": ""}, {"path": "frontend/src/components/fleet/dashboardLayout.js", "orig": "0eb9de60b7310f4212316879e5346df1eea2c52d354930b73945275a2415eb4e", "new": "f89fb9442c9e778f48bd6b66dc737d474cd090c0824ab135efdd9f841b0e0333", "blob": ""}, {"path": "frontend/src/components/StrategyHost.jsx", "orig": "4ac3927d3744ec261ff190d3befc582bb1604f6d75c2379c9d4211b6b80aad2f", "new": "d2bf0ac3bd144e8bddfae0f3cfcc5c02a8275d9c9e0179e1579be46dd7722ffa", "blob": ""}, {"path": "backend/app/api/live_replay_routes.py", "orig": "6413a2b5675b0f76bf58adae59eb7766b9729279eb26e498b8bf9286575ba6bd", "new": "064e31f4d9bb584ebf2b3d275eaa2e3f3342596aa3524e86cef11ae125c3abaa", "blob": ""}, {"path": "backend/app/api/app_settings_api.py", "orig": "9109120ab68936d7b9f3f2ce552d72e06db872c73d5a29e2ea73cc429c80e1f4", "new": "822c5d42b3ee44a6261e433a3132803d4e18af525ec211077a5a78d35c707bec", "blob": ""}, {"path": "backend/app/api/test_dash_calm_routes.py", "orig": null, "new": "c3fc4197fc63d6893e86c34c7629e5d3a99040f29489769670032453c4013a31", "blob": ""}, {"path": "frontend/uitest/calm_fixture.py", "orig": null, "new": "a31daa2f08e782e85277c79f57833f384de7dbf4d96a082a1fbecfd59e700df6", "blob": ""}, {"path": "frontend/uitest/shot_calm.py", "orig": null, "new": "4b05cf64d3d2bc96c7950f16585087ef4181ead669a903a2480d5d68faf79e7e", "blob": ""}, {"path": "frontend/uitest/test_ui_calm.py", "orig": null, "new": "6c9249ea2789657c556a07fb07c6663763dbc811df310081f1cce576e2c2a7b3", "blob": ""}, {"path": "frontend/uitest/README.md", "orig": "ec7ae88d4630b98804ce5f974616eb5741a1eb540576003a30ae6cbd246dfef4", "new": "a1e75a17bd8641e4e34c1e6c3faa2f0f22214c4dd0c093849467a92496c590ca", "blob": ""}, {"path": "frontend/uitest/livechart_scene.py", "orig": "b5a212c2ecfa5517ff4fa594f9c97ec4305d6d8a2dca9b495b433b4d19c19490", "new": "6f8ae45e1a2e0359db92083db5611a975beff6c97b75f1593c65038341c44547", "blob": ""}, {"path": "frontend/uitest/shot_dashboard.py", "orig": "a96d4b58011a83eac8934927d551c0467b86b56bae748fbc9dbadbb1d927967b", "new": "76c6bb0d0c34d8ecd3cbaedb0099af4bbd71678adde83f15a91d86e0fe9dc4fa", "blob": ""}, {"path": "frontend/uitest/test_ui_live_chart.py", "orig": "c4d186f087068d5d7004e46d12a9d6c68e2913fed8f5ea411ebed6f3ecddbd92", "new": "383ce7bfdb551e5f32eea5a0f8818aec4b98a2278cde6edc6fedc5687ec10f84", "blob": ""}, {"path": "frontend/uitest/test_ui_dash_system.py", "orig": "86c3c06e146ac51ac7c585d3f7591e99b413d0964a7c094ae6104b6c893cf74e", "new": "d5ae7b800046c8f7ecce3867111501a2690e053b290b64f389c69a5f021ac283", "blob": ""}, {"path": "frontend/uitest/test_ui_off_hidden.py", "orig": "f38dcde6f16dbf5070849fcaf9d4d74c00cc62bacc8dc9c4e438dff507852f1b", "new": "7dc693dd90f001ca0f29cffad7913135536022e8437d0600f4239e56747a18db", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/api/test_dash_calm_routes.py", "app/api/test_replay_meter_route.py", "app/api/test_app_settings_pages.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_book_strip.py (and everything before it)
if "--rollback" not in args:
    _k = os.path.join(repo, "frontend", "src", "components", "fleet", "FleetKpis.jsx")
    if "BOOK_STRIP_20261117" not in (open(_k, encoding="utf-8").read() if os.path.exists(_k) else ""):
        die("run apply_book_strip.py first (after apply_dash_system.py) — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # the earlier scripts' output is expected to be uncommitted still: every planned
        # file was just proven byte-identical to it (sha == orig), so only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="dash_calm_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_dash_calm.py --rollback")
